    86→      }
    87→    } catch (e) {
    88→      console.error('Invalid WebSocket message:', e);
    89→    }
    90→  });
    91→
    92→  ws.on('close', () => {
    93→    console.log('Client disconnected from live tail');
    94→    liveTailClients.delete(ws);
    95→  });
