   103→// Poll for new logs and broadcast to connected clients
   104→let lastTimestamp = new Date().toISOString();
   105→
   106→async function pollNewLogs(): Promise<void> {
   107→  if (liveTailClients.size === 0) return;
   108→
   109→  try {
   110→    const logs = await executeQuery<Record<string, unknown>>(
   111→      `SELECT * FROM lognog.logs
   112→       WHERE timestamp > parseDateTimeBestEffort('${lastTimestamp}')
   113→       ORDER BY timestamp ASC
   114→       LIMIT 100`
   115→    );
   116→
   117→    if (logs.length > 0) {
   118→      lastTimestamp = String(logs[logs.length - 1].timestamp);
   119→
   120→      const message = JSON.stringify({
   121→        type: 'logs',
   122→        data: logs,
   123→      });
   124→
   125→      for (const client of liveTailClients) {
   126→        if (client.readyState === WebSocket.OPEN) {
   127→          client.send(message);
   128→        }
   129→      }
   130→    }
   131→  } catch (error) {
   132→    console.error('Error polling for new logs:', error);
   133→  }
   134→}
   135→
   136→// Poll every 2 seconds
   137→setInterval(pollNewLogs, 2000);
