   139→// SSE endpoint for live tail (works with both backends)
   140→interface SSEClient {
   141→  res: express.Response;
   142→  query?: string;
   143→  lastTimestamp: string;
   144→}
   145→
   146→const sseClients: Set<SSEClient> = new Set();
   147→
   148→app.get('/sse/tail', (req: express.Request, res: express.Response) => {
   149→  const query = req.query.query as string || 'search *';
   150→
   151→  // Set SSE headers
   152→  res.setHeader('Content-Type', 'text/event-stream');
   153→  res.setHeader('Cache-Control', 'no-cache');
   154→  res.setHeader('Connection', 'keep-alive');
   155→  res.setHeader('Access-Control-Allow-Origin', '*');
   156→  res.flushHeaders();
   157→
   158→  const client: SSEClient = {
   159→    res,
   160→    query,
   161→    lastTimestamp: new Date().toISOString(),
   162→  };
   163→
   164→  sseClients.add(client);
   165→  console.log(`SSE client connected (${sseClients.size} total), query: ${query}`);
   166→
   167→  // Send initial connection message
   168→  res.write(`data: ${JSON.stringify({ type: 'connected', message: 'Live tail connected' })}\n\n`);
   169→
   170→  // Handle client disconnect
   171→  req.on('close', () => {
   172→    sseClients.delete(client);
   173→    console.log(`SSE client disconnected (${sseClients.size} remaining)`);
   174→  });
   175→});
   176→
   177→// Poll and send new logs to SSE clients
   178→async function pollSSEClients(): Promise<void> {
   179→  if (sseClients.size === 0) return;
   180→
   181→  for (const client of sseClients) {
   182→    try {
   183→      // Use DSL query with time filter
   184→      const earliest = client.lastTimestamp;
   185→      const latest = new Date().toISOString();
   186→
   187→      const { results } = await executeDSLQuery(client.query || 'search *', { earliest, latest });
   188→
   189→      if (results.length > 0) {
   190→        // Update last timestamp to the newest result
   191→        const timestamps = results.map((r: Record<string, unknown>) => r.timestamp as string).filter(Boolean);
   192→        if (timestamps.length > 0) {
   193→          client.lastTimestamp = timestamps[timestamps.length - 1];
   194→        }
   195→
   196→        // Send logs to client
   197→        const message = JSON.stringify({
   198→          type: 'logs',
   199→          count: results.length,
   200→          data: results.slice(0, 100), // Limit to 100 per update
   201→        });
   202→
   203→        client.res.write(`data: ${message}\n\n`);
   204→      }
   205→    } catch (error) {
   206→      console.error('Error polling for SSE client:', error);
   207→      // Send error to client
   208→      client.res.write(`data: ${JSON.stringify({ type: 'error', message: 'Query error' })}\n\n`);
   209→    }
   210→  }
   211→}
   212→
   213→// Poll SSE clients every 2 seconds
   214→setInterval(pollSSEClients, 2000);
