   178→async function pollSSEClients(): Promise<void> {
   179→  if (sseClients.size === 0) return;
   180→
   181→  for (const client of sseClients) {
   182→    try {
   183→      // Use DSL query with time filter
   184→      const earliest = client.lastTimestamp;
   185→      const latest = new Date().toISOString();
   186→
   187→      const { results } = await executeDSLQuery(client.query || 'search *', { earliest, latest });
   188→
   189→      if (results.length > 0) {
   190→        // Update last timestamp to the newest result
   191→        const timestamps = results.map((r: Record<string, unknown>) => r.timestamp as string).filter(Boolean);
   192→        if (timestamps.length > 0) {
   193→          client.lastTimestamp = timestamps[timestamps.length - 1];
   194→        }
   195→
   196→        // Send logs to client
   197→        const message = JSON.stringify({
   198→          type: 'logs',
   199→          count: results.length,
   200→          data: results.slice(0, 100), // Limit to 100 per update
   201→        });
   202→
   203→        client.res.write(`data: ${message}\n\n`);
   204→      }
   205→    } catch (error) {
   206→      console.error('Error polling for SSE client:', error);
   207→      // Send error to client
